insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'bijou', '珠宝', 'Bijou', '', 'classic', '💎', '#d9b45a', '马天尼杯', '高', '19 世纪末的经典，金酒 + 甜味美思 + 荨麻酒，名字取自三种酒的颜色像三颗宝石。', '', '', '', '["甜","草本","浓郁","短饮","烈","餐后"]'::jsonb, '[{"id":"gin","amount":"45 ml"},{"id":"sweet-vermouth","amount":"20 ml"},{"id":"chartreuse","amount":"15 ml"},{"id":"orange-bitters","amount":"1 dash"}]'::jsonb, '["材料加冰搅拌 20 秒","滤入冰镇马天尼杯","柠檬皮挤香后放入杯中"]'::jsonb, 'zhubao', 'Z', 'u-admin', '官方', 'approved', 0, now())
