insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'dirty-martini', '脏马天尼', 'Dirty Martini', '', 'classic', '🫒', '#b8b09a', '马天尼杯', '高', '在马天尼里加一勺腌橄榄的盐水，酒体会变浑浊（所以叫「脏」），咸香很上头。', '', '', '', '["咸","草本","清爽","短饮","烈","餐前"]'::jsonb, '[{"id":"gin","amount":"60 ml"},{"id":"dry-vermouth","amount":"10 ml"},{"id":"olive","amount":"2 颗"},{"id":"salt","amount":"少许"}]'::jsonb, '["材料加冰搅拌 20 秒","连一勺腌橄榄的盐水一起滤入冰镇马天尼杯","放两颗橄榄装饰"]'::jsonb, 'zangmatianni', 'Z', 'u-admin', '官方', 'approved', 0, now())
on conflict (id) do nothing;
insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'vodka-martini', '伏特加马天尼', 'Vodka Martini', '', 'classic', '🍸', '#dcd8cc', '马天尼杯', '高', '把金酒换成伏特加，杜松子香没了，口感更干净，007 点的那杯就是它。', '', '', '', '["清爽","短饮","烈","餐前"]'::jsonb, '[{"id":"vodka","amount":"60 ml"},{"id":"dry-vermouth","amount":"10 ml"},{"id":"lemon","amount":"1 片皮","optional":true}]'::jsonb, '["材料加冰搅拌 20 秒","滤入冰镇马天尼杯","柠檬皮挤香后装饰"]'::jsonb, 'futejiamatianni', 'F', 'u-admin', '官方', 'approved', 0, now())
