insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'death-in-the-afternoon', '午后之死', 'Death in the Afternoon', '', 'classic', '💀', '#e7d98a', '香槟杯', '高', '海明威自己发明的：苦艾酒加香槟。倒进去会变成乳白色，也叫「海明威效应」。', '', '', '', '["草本","气泡","短饮","烈","餐后"]'::jsonb, '[{"id":"absinthe","amount":"15 ml"},{"id":"sparkling","amount":"90 ml"}]'::jsonb, '["香槟杯中先倒入苦艾酒","缓慢注入冰镇起泡酒","看着它变成乳白色，轻轻搅一下"]'::jsonb, 'wuhouzhisi', 'W', 'u-admin', '官方', 'approved', 0, now())
on conflict (id) do nothing;
insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'boston-sour', '波士顿酸', 'Boston Sour', '', 'classic', '🍋', '#e8c98a', '古典杯', '中', '威士忌酸加蛋白，摇出绵密的奶盖感，是酸酒家族里最讨喜的一支。', '', '', '', '["酸","绵密","奶香","短饮","中等","餐后"]'::jsonb, '[{"id":"bourbon","amount":"50 ml"},{"id":"lemon-juice","amount":"20 ml"},{"id":"simple-syrup","amount":"15 ml"},{"id":"egg-white","amount":"1 个"},{"id":"angostura","amount":"1 dash","optional":true}]'::jsonb, '["除苦精外全部材料加冰大力摇 12 秒","滤掉冰再干摇一次，让蛋白起泡","滤入放冰的古典杯","表面滴两滴苦精"]'::jsonb, 'boshidunsuan', 'B', 'u-admin', '官方', 'approved', 0, now())
on conflict (id) do nothing;
