  'bahama-mama', '巴哈马妈妈', 'Bahama Mama', '', 'classic', '🌴', '#e07a3a', '高球杯', '中', '热带派对的常客，朗姆 + 椰香 + 两种果汁，甜得像在度假。', '', '', '', '["甜","果香","长饮","中等","夏日","派对"]'::jsonb, '[{"id":"dark-rum","amount":"30 ml"},{"id":"malibu","amount":"20 ml"},{"id":"pineapple-juice","amount":"60 ml"},{"id":"orange-juice","amount":"30 ml"},{"id":"grenadine","amount":"10 ml"},{"id":"ice","amount":"满杯"}]'::jsonb, '["全部材料加冰摇匀","滤入放冰的高球杯","菠萝片与樱桃装饰"]'::jsonb, 'bahamama', 'B', 'u-admin', '官方', 'approved', 0, now())
