insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'caipirissima', '卡琵莉西玛', 'Caipirissima', '', 'classic', '🍈', '#a8d98a', '古典杯', '中', '卡琵利亚的朗姆版本，做法一模一样，把甘蔗酒换成白朗姆就好。', '', '', '', '["酸","甜","清爽","短饮","中等","夏日"]'::jsonb, '[{"id":"white-rum","amount":"60 ml"},{"id":"lime","amount":"1 个"},{"id":"sugar","amount":"2 茶匙"},{"id":"ice","amount":"碎冰满杯"}]'::jsonb, '["青柠切块，与糖一起轻捣出汁","加入白朗姆与碎冰","搅拌至杯壁结霜"]'::jsonb, 'kapilixima', 'K', 'u-admin', '官方', 'approved', 0, now())
