  'algonquin', '阿尔冈琴', 'Algonquin', '', 'classic', '🖋️', '#d9a441', '马天尼杯', '高', '纽约阿尔冈琴酒店的老配方，黑麦威士忌配菠萝汁，酸得意外地协调。', '', '', '', '["酸","果香","清爽","短饮","烈","餐前"]'::jsonb, '[{"id":"rye","amount":"45 ml"},{"id":"dry-vermouth","amount":"15 ml"},{"id":"pineapple-juice","amount":"15 ml"}]'::jsonb, '["材料加冰摇匀","滤入冰镇马天尼杯","不加装饰，直接喝"]'::jsonb, 'aergangqin', 'A', 'u-admin', '官方', 'approved', 0, now())
