insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'mulled-wine', '热红酒', 'Mulled Wine', '', 'classic', '🍷', '#a8503a', '马克杯', '低', '圣诞集市的香气：红酒加橙子和香料微微加热，注意千万别煮沸。', '', '', '', '["甜","果香","长饮","微醺","冬日","派对"]'::jsonb, '[{"id":"red-wine","amount":"200 ml"},{"id":"orange","amount":"1 个"},{"id":"honey","amount":"30 ml"},{"id":"cinnamon-stick","amount":"1 根"},{"id":"clove","amount":"5 颗"},{"id":"star-anise","amount":"2 颗"}]'::jsonb, '["橙子切片，与红酒、香料一起小火加热至微微冒热气","关火前加蜂蜜调味，不要煮沸","焖 10 分钟后滤入杯中"]'::jsonb, 'rehongjiu', 'R', 'u-admin', '官方', 'approved', 0, now())
on conflict (id) do nothing;
insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'red-snapper', '红鲷鱼', 'Red Snapper', '', 'classic', '🐟', '#d94a3a', '高球杯', '低', '血腥玛丽的琴酒版本——其实比原版更早，用金酒配番茄汁和香料。', '', '', '', '["咸","酸","清爽","长饮","微醺","餐前"]'::jsonb, '[{"id":"gin","amount":"45 ml"},{"id":"tomato-juice","amount":"120 ml"},{"id":"lemon-juice","amount":"15 ml"},{"id":"worcestershire","amount":"3 滴"},{"id":"tabasco","amount":"2 滴"},{"id":"celery-salt","amount":"少许"},{"id":"pepper","amount":"少许"}]'::jsonb, '["全部材料倒入调酒杯，加冰来回滚动混合","滤入放冰的高球杯","芹菜杆与柠檬角装饰"]'::jsonb, 'hongdiaoyu', 'H', 'u-admin', '官方', 'approved', 0, now())
