insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'tequila-sour', '龙舌兰酸', 'Tequila Sour', '', 'classic', '🌵', '#d9e08a', '古典杯', '中', '龙舌兰的植物感配上蛋白，酸酒里最有「人味」的一杯。', '', '', '', '["酸","绵密","清爽","短饮","中等","餐前"]'::jsonb, '[{"id":"tequila","amount":"50 ml"},{"id":"lemon-juice","amount":"20 ml"},{"id":"simple-syrup","amount":"15 ml"},{"id":"egg-white","amount":"1 个"},{"id":"angostura","amount":"1 dash","optional":true}]'::jsonb, '["除苦精外加冰大力摇 12 秒","滤掉冰再干摇起泡","滤入放冰的古典杯，表面滴苦精"]'::jsonb, 'longsheliansuan', 'L', 'u-admin', '官方', 'approved', 0, now())
