insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'b-53', 'B-53 轰炸机', 'B-53', '', 'classic', '🎯', '#4a3a2a', '子弹杯', '高', '三层分层的经典小杯，一层咖啡、一层奶酒、一层苦艾，一口下去。', '', '', '', '["甜","奶香","短饮","烈","餐后","派对"]'::jsonb, '[{"id":"kahlua","amount":"20 ml"},{"id":"baileys","amount":"20 ml"},{"id":"absinthe","amount":"20 ml"}]'::jsonb, '["子弹杯中先倒咖啡利口酒","沿匙背缓慢倒入奶酒，形成第二层","再沿匙背倒苦艾酒，分层明显即可"]'::jsonb, 'b53hongzhaji', 'B', 'u-admin', '官方', 'approved', 0, now())
