insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'french-martini', '法兰西马天尼', 'French Martini', '', 'classic', '🇫🇷', '#d95a8a', '马天尼杯', '中', '90 年代纽约的爆款，伏特加 + 黑莓利口酒 + 菠萝汁，摇出来带一层细泡沫。', '', '', '', '["甜","果香","绵密","短饮","中等","派对"]'::jsonb, '[{"id":"vodka","amount":"45 ml"},{"id":"chambord","amount":"15 ml"},{"id":"pineapple-juice","amount":"45 ml"}]'::jsonb, '["材料加冰大力摇匀","滤入冰镇马天尼杯","菠萝叶或柠檬皮装饰"]'::jsonb, 'falaximatianni', 'F', 'u-admin', '官方', 'approved', 0, now())
