insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'pornstar-martini', '明星马天尼', 'Pornstar Martini', '', 'classic', '⭐', '#f2c05a', '马天尼杯', '中', '百香果风味的现代经典，旁边配一小杯起泡酒，一口酒一口香槟交替喝。', '', '', '', '["甜","酸","果香","气泡","短饮","中等","夏日","派对"]'::jsonb, '[{"id":"vodka","amount":"40 ml"},{"id":"passionfruit-syrup","amount":"20 ml"},{"id":"passionfruit","amount":"1 个"},{"id":"lime-juice","amount":"10 ml"},{"id":"sparkling","amount":"60 ml"}]'::jsonb, '["百香果对半切开，取一半果肉入杯","加伏特加、百香果糖浆与青柠汁，加冰摇匀","滤入冰镇马天尼杯，放半颗百香果","另配一小杯冰起泡酒一起上"]'::jsonb, 'mingxingmatianni', 'M', 'u-admin', '官方', 'approved', 0, now())
