insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'miami-vice', '迈阿密风云', 'Miami Vice', '', 'classic', '🍹', '#f2a0a0', '高球杯', '中', '80 年代的产物：一半椰香朗姆冰沙，一半草莓冰沙，同时倒进杯子就有了分层。', '', '', '', '["甜","果香","冰沙","长饮","中等","夏日","派对"]'::jsonb, '[{"id":"white-rum","amount":"30 ml"},{"id":"malibu","amount":"15 ml"},{"id":"pineapple-juice","amount":"45 ml"},{"id":"strawberry","amount":"3 颗"},{"id":"lime-juice","amount":"10 ml"},{"id":"ice","amount":"两杯"}]'::jsonb, '["朗姆、椰香酒、菠萝汁加冰打成椰香冰沙","另一份加草莓与青柠汁打成草莓冰沙","两种冰沙同时从两侧倒入杯中形成分层","菠萝片与草莓装饰"]'::jsonb, 'maiamifengyun', 'M', 'u-admin', '官方', 'approved', 0, now())
