insert into recipes (id, name, en, alias, type, emoji, color, glass, abv, "desc", image, video, video_name, tags, items, steps, py, initial, author_id, author, status, views, created_at) values (
  'sangria', '桑格利亚', 'Sangria', '', 'classic', '🍇', '#a83a4a', '大杯', '低', '西班牙的水果红酒，提前泡一大壶，聚会时最省事也最受欢迎。', '', '', '', '["甜","果香","清爽","长饮","微醺","夏日","派对"]'::jsonb, '[{"id":"red-wine","amount":"300 ml"},{"id":"orange","amount":"1 个"},{"id":"apple","amount":"1 个"},{"id":"lemon","amount":"半个"},{"id":"brandy","amount":"30 ml"},{"id":"sugar","amount":"2 茶匙"},{"id":"sparkling-water","amount":"适量","optional":true}]'::jsonb, '["橙子、苹果、柠檬切块放入壶中","倒入红酒、白兰地与糖拌匀","冷藏浸泡 2 小时以上","喝时倒进放冰的大杯，可加一点气泡水"]'::jsonb, 'sangeliya', 'S', 'u-admin', '官方', 'approved', 0, now())
